describe('File Upload - File Input and Submission', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/upload');
  });

  it('should successfully upload a file and display confirmation', () => {
    // Create a dummy file for upload
    const testFile = Cypress.Buffer.from('This is a test file content');

    // Intercept the file upload API endpoint
    cy.intercept('POST', '/upload').as('fileUpload');

    // Upload the file by attaching the buffer to the file input
    cy.get('[data-testid="file-upload"]').selectFile(testFile, { force: true });

    // Verify the file name is displayed before submission
    cy.get('[data-testid="uploaded-file-name"]').should('contain', 'test-file.txt');

    // Click the submit button
    cy.get('[data-testid="file-submit"]').click();

    // Wait for the API call
    cy.wait('@fileUpload');

    // Verify navigation to the success page
    cy.url().should('include', '/upload');

    // Verify success heading is displayed
    cy.get('[data-testid="success-heading"]').should('be.visible').should('contain', 'File Uploaded!');

    // Verify the uploaded file name is displayed in the confirmation area
    cy.get('[data-testid="uploaded-files"]').should('be.visible').should('contain', 'test-file.txt');
  });

  it('should handle file upload with invalid file type and display error', () => {
    // Create a dummy file with an invalid extension
    const invalidFile = Cypress.Buffer.from('This is not a valid file');

    // Intercept the file upload API endpoint
    cy.intercept('POST', '/upload', { statusCode: 400, body: { error: 'Invalid file type' } }).as('fileUploadError');

    // Attempt to upload the invalid file
    cy.get('[data-testid="file-upload"]').selectFile(invalidFile, { force: true });

    // Click the submit button
    cy.get('[data-testid="file-submit"]').click();

    // Wait for the error response
    cy.wait('@fileUploadError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid file type');

    // Verify success heading is NOT displayed
    cy.get('[data-testid="success-heading"]').should('not.exist');

    // Verify uploaded files list is empty
    cy.get('[data-testid="uploaded-files"]').should('not.exist');
  });
});
